你可以使用 Go 的 `os/exec` 包来执行系统命令来自动打开本地 HTML 文件并截图保存为 PNG 图片。 

以下是一个实现该功能的例子，使用了 Chrome 浏览器和 Puppeteer 工具：

```go
package main

import (
    "context"
    "io/ioutil"
    "log"
    "os"
    "os/exec"
    "path/filepath"
    "strconv"
    "strings"
    "time"

    "github.com/chromedp/cdproto/cdp"
    "github.com/chromedp/cdproto/emulation"
    "github.com/chromedp/chromedp"
)

func main() {
    // 读取本地 HTML 文件
    path := "./index.html"
    data, err := ioutil.ReadFile(path)
    if err != nil {
        log.Fatalf("Failed to read file: %v", err)
    }
    content := string(data)

    // 启动 Chrome 浏览器及 Puppeteer 工具
    ctx, cancel := chromedp.NewContext(context.Background())
    defer cancel()
    if err := chromedp.Run(ctx); err != nil {
        log.Fatalf("Failed to start Chrome: %v", err)
    }

    // 设置浏览器窗口大小和 DPI
    var buf []byte
    if err := chromedp.Run(ctx,
        emulation.SetDeviceMetricsOverride(1920, 1080, 1.0, false),
        emulation.SetCPUThrottlingRate(4),
        chromedp.Navigate("http://localhost/"), // 打开本地 HTML 文件
        chromedp.Sleep(2 * time.Second), // 等待界面加载完成
        chromedp.ActionFunc(func(ctx context.Context) error {
            // 获取网页内容并创建 Screenshot
            nodes, err := dom.getDocument().Do(ctx)
            if err != nil {
                return err
            }
            content, err = dom.getOuterHTML(nodes.NodeID).Do(ctx)
            if err != nil {
                return err
            }
            buf, err = page.CaptureScreenshot().WithQuality(90).WithClip(&cdp.Rect{X: 0, Y: 0, Width: 1920, Height: 1080}).Do(ctx)
            if err != nil {
                return err
            }
            return nil
        }),
    ); err != nil {
        log.Fatalf("Failed to capture screenshot: %v", err)
    }

    // 保存 screenshot
    err = ioutil.WriteFile(filepath.Join(".", "screenshot.png"), buf, 0644)
    if err != nil {
        log.Fatalf("Failed to save screenshot: %v", err)
    }

    log.Print("Screenshot saved successfully")
}

```

注意，这个例子中使用了 Chrome 浏览器和 Puppeteer 工具，你需要先安装这些工具。在macOS或Linux系统中，你可以按照以下命令来安装它们：

```bash
# 安装 Chrome 浏览器（macOS）
brew install --cask google-chrome

# 安装 Chrome 浏览器（Ubuntu）
sudo apt-get update
sudo apt-get install google-chrome-stable

# 安装 Puppeteer（macOS）
npm install puppeteer

# 安装 Puppeteer（Ubuntu）
sudo npm install -g puppeteer
``` 

在 Windows 系统中也可以使用这些工具，但需要手动下载和安装。

