    err = png.Encode(&buf, img)
    if err != nil {
        log.Printf("Failed to convert page %d: %v", pageNum+1, err)
        continue
    }

    filename := fmt.Sprintf("page-%d.png", pageNum+1)
    err = os.WriteFile(filepath.Join(".", filename), buf.Bytes(), 0644)
    if err != nil {
        log.Printf("Failed to write file %s: %v", filename, err)
        continue
    }
    log.Printf("Page %d saved as %s", pageNum+1, filename)
}
```

完整代码示例：

```go
package main

import (
	"bytes"
	"fmt"
	"image/png"
	"log"
	"os"
	"path/filepath"

	"github.com/jung-kurt/gofpdf"
)

func main() {
	// 创建一个新的 pdfReader 并加载 pdf 文件。
	pdfReader := gofpdf.NewImportReader()
	err := pdfReader.Load("./example.pdf")
	if err != nil {
		log.Fatal(err)
	}

	// 获取 pdfReader 中的 ImportList。
	pdfArray := pdfReader.ImportList()

	// 遍历 ImportList 中的每一页 pdf。
	for pageNum, pdfPage := range pdfArray {
		// 将 pdfReader 的当前页指向当前的 pdfPage。
		pdfReader.SetPage(pdfPage)

		// 将当前页的 pdf 渲染为 image.Image。
		img := pdfReader.Image()

		// 将 image.Image 转换为 PNG 图片并保存。
		var buf bytes.Buffer
		err = png.Encode(&buf, img)
		if err != nil {
			log.Printf("Failed to convert page %d: %v", pageNum+1, err)
			continue
		}

		filename := fmt.Sprintf("page-%d.png", pageNum+1)
		err = os.WriteFile(filepath.Join(".", filename), buf.Bytes(), 0644)
		if err != nil {
			log.Printf("Failed to write file %s: %v", filename, err)
			continue
		}
		log.Printf("Page %d saved as %s", pageNum+1, filename)
	}
}
```

这个例子读取名为 `example.pdf` 的 PDF 文件，并将其转换为 PNG 图像。PNG 图像将保存在当前工作目录下，以 `page-1.png`， `page-2.png` 等命名。你也可以根据你的需求自定义图片保存路径和文件名。

注意，由于图像转换可能需要一些时间，所以在转换多页 PDF 文件时需要选择一种异步或并发方式来转换它们。
